    async fn migrated_db() -> (tempfile::TempDir, DatabaseConnection) {
        let temp_dir = tempfile::TempDir::new().expect("temp dir");
        let db = test_db_connection(temp_dir.path()).await;
        apply_migrations(&db, false)
            .await
            .expect("migrations should apply");
        (temp_dir, db)
    }

    /// The test schemas are isolated through `search_path` (see
    /// `jupiter::tests`) while the catalog spans every schema, so every
    /// catalog query here must be scoped to `current_schema()`.
    async fn scalar(db: &DatabaseConnection, sql: &str) -> Option<String> {
        let row = db
            .query_one_raw(Statement::from_string(DbBackend::Postgres, sql.to_owned()))
            .await
            .expect("catalog query")?;
        row.try_get::<Option<String>>("", "value")
            .expect("value column")
    }

    async fn enum_labels(db: &DatabaseConnection, type_name: &str) -> Option<Vec<String>> {
        let labels = scalar(
            db,
            &format!(
                "SELECT string_agg(e.enumlabel, ',' ORDER BY e.enumsortorder) AS value \
                 FROM pg_type t \
                 JOIN pg_namespace n ON n.oid = t.typnamespace \
                 JOIN pg_enum e ON e.enumtypid = t.oid \
                 WHERE n.nspname = current_schema() AND t.typname = '{type_name}'"
            ),
        )
        .await?;
        Some(labels.split(',').map(str::to_owned).collect())
    }

    /// `(data_type, is_nullable)` of a column in the current schema.
    async fn column(db: &DatabaseConnection, table: &str, name: &str) -> Option<(String, String)> {
        let row = db
            .query_one_raw(Statement::from_string(
                DbBackend::Postgres,
                format!(
                    "SELECT data_type, is_nullable FROM information_schema.columns \
                     WHERE table_schema = current_schema() AND table_name = '{table}' \
                     AND column_name = '{name}'"
                ),
            ))
            .await
            .expect("catalog query")?;
        Some((
            row.try_get("", "data_type").expect("data_type"),
            row.try_get("", "is_nullable").expect("is_nullable"),
        ))
    }

